class MainDispatcherRule(
    private val dispatcher: TestDispatcher = UnconfinedTestDispatcher()
) : TestWatcher() {
    override fun starting(description: Description) = Dispatchers.setMain(dispatcher)
    override fun finished(description: Description) = Dispatchers.resetMain()
}

class ProfileViewModelTest {
    @get:Rule val mainRule = MainDispatcherRule()

    @Test
    fun loadsProfile() = runTest {
        val viewModel = ProfileViewModel(FakeUserRepository())
        assertEquals("Ana", viewModel.state.value.name)
    }
}

class CounterTest {
    @get:Rule val composeRule = createComposeRule()

    @Test
    fun incrementsOnClick() {
        composeRule.setContent { Counter() }

        composeRule.onNodeWithText("Clicked 0 times").performClick()

        composeRule.onNodeWithText("Clicked 1 times").assertIsDisplayed()
    }
}

class FakeUserRepository : UserRepository {
    private val users = MutableStateFlow<List<User>>(emptyList())

    override fun observeUsers(): Flow<List<User>> = users

    override suspend fun addUser(user: User) {
        users.value = users.value + user
    }
}

@Test
fun showsAddedUser() = runTest {
    val repo = FakeUserRepository()
    repo.addUser(User("1", "Ana"))
    assertEquals(listOf("Ana"), repo.observeUsers().first().map { it.name })
}
